/// VM replay implementations for net bindings.
#[inline]
fn destack_net_accept_vm_replay(
    runtime: &RuntimeCallContext,
    context: &mut vm::RuntimeContext<'_>,
    listener: resource::ListenerHandle,
    flags: AcceptFlags,
) -> RuntimeResult<vm::Value> {
    let result = runtime.replay().run_binding_with_context(
        ACCEPT,
        context,
        |context| platform_vm::destack_net_accept(runtime, context, listener, flags),
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value = *value;
                let result_replay = result_value;
                let payload = AcceptReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    AcceptReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    );
    let result = encode_destack_net_accept_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_net_local_address_vm_replay(
    runtime: &RuntimeCallContext,
    context: &mut vm::RuntimeContext<'_>,
    handle: resource::SocketHandle,
) -> RuntimeResult<vm::Value> {
    let result = runtime.replay().run_binding_with_context(
        LOCAL_ADDRESS,
        context,
        |context| platform_vm::destack_net_local_address(runtime, context, handle),
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value = *value;
                let result_replay_family = result_value.family;
                let result_replay_length = result_value.length;
                let result_replay_bytes = result_value.bytes.read_bytes(context)?;
                let result_replay = SocketAddressReplay {
                    family: result_replay_family,
                    length: result_replay_length,
                    bytes: result_replay_bytes,
                };
                let payload = LocalAddressReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    LocalAddressReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result_family = value.family;
                    let vm_result_length = value.length;
                    let vm_result_bytes = VmArray::from_bytes(context, value.bytes.as_slice());
                    let vm_result = SocketAddressVm {
                        family: vm_result_family,
                        length: vm_result_length,
                        bytes: vm_result_bytes,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    );
    let result = encode_destack_net_local_address_result(context, result)?;
    Ok(result)
}

